/* Original SVG illustrations, authored for Tryvo. No remote image dependencies. */
window.TryvoArt = (() => {
  const tree=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><ellipse cy="18" rx="22" ry="9" fill="#719c8c" opacity=".2"/><path d="M0 0v18" stroke="#617c65" stroke-width="5"/><path d="M-20 0Q-24-20-10-24Q2-46 15-24Q35-13 19 3Q0 15-20 0" fill="#85bda3"/><path d="M0 10Q18 3 19-12Q9 2 0 0Z" fill="#64a68c"/></g>`;
  const window=(x,y)=>`<rect x="${x}" y="${y}" width="13" height="20" rx="3" fill="#cce4ef" stroke="#416b96" stroke-width="2"/><path d="M${x+6.5} ${y}v20" stroke="#416b96"/>`;
  function building(id){
    const base='<ellipse cx="0" cy="16" rx="106" ry="28" fill="#2b557d" opacity=".12"/>';
    if(id==='investigation')return `${base}<path d="m-88-2 80-28 100 28-80 32Z" fill="#c1cfdd"/><path d="M-70-95H70V3H-70Z" fill="#f8fafb" stroke="#5479a9" stroke-width="2"/><path d="m70-95 25-15V-9L70 3" fill="#9db7d6"/><path d="m-80-95 80-52 80 52Z" fill="#345b9c"/><path d="m0-147 80 52 25-15-80-52Z" fill="#24477e"/><rect x="-22" y="-48" width="44" height="51" rx="3" fill="#315c9c"/><path d="M0-48V3" stroke="#7091bd" stroke-width="2"/>${window(-53,-70)}${window(40,-70)}<circle cy="-105" r="16" fill="#f2b84b"/><circle cy="-107" r="6" fill="none" stroke="#254879" stroke-width="3"/><path d="m5-101 6 6" stroke="#254879" stroke-width="3"/><rect x="-30" y="-9" width="60" height="8" fill="#c7d6e5"/><path d="M-38 5h76M-45 12h90" stroke="#a9bacf" stroke-width="5"/>`;
    if(id==='strategy')return `${base}<path d="M-70-70H64V5H-70Z" fill="#f1edf8" stroke="#8c70b1" stroke-width="2"/><path d="m64-70 26-15V-7L64 5" fill="#b6a4d0"/><path d="m-80-70 70-54 85 54Z" fill="#9678bb"/><path d="m-10-124 85 54 25-15-85-54Z" fill="#73539d"/><rect x="-50" y="-60" width="17" height="65" rx="2" fill="#d8c9e8"/><rect x="34" y="-60" width="17" height="65" rx="2" fill="#d8c9e8"/><path d="M-16 5v-38a20 20 0 0 1 40 0V5" fill="#68518a"/><path d="M-10-123v-43" stroke="#5f477c" stroke-width="3"/><path d="m-9-164 41 7-41 16Z" fill="#f2b84b"/><rect x="-74" y="6" width="145" height="8" rx="3" fill="#c7b8dc"/>`;
    if(id==='logic')return `${base}<path d="M-80-68H30V8H-80Z" fill="#e6f5ee" stroke="#5b9b89" stroke-width="2"/><path d="m30-68 50-29V-21L30 8" fill="#95c7b5"/><path d="m-80-68 45-30H80L30-68Z" fill="#c7e7db"/><path d="M-57-105H-2v38h-55Z" fill="#e6f5ee" stroke="#5b9b89" stroke-width="2"/><path d="m-57-105 24-16H22L-2-105Z" fill="#80b6a3"/><path d="M-2-105 22-121v38L-2-67" fill="#76ac99"/><rect x="-61" y="-43" width="33" height="30" rx="4" fill="#5d988d"/><path d="M-45-43v30M-61-28h33" stroke="#e6f5ee" stroke-width="3"/><rect x="-10" y="-37" width="24" height="45" fill="#397e74"/><path d="m40-36 12-7v21l-12 7m25-36 10-6v21l-10 6" fill="#e4f6ed"/>`;
    if(id==='numbers')return `${base}<path d="M-85-60H75V8H-85Z" fill="#fff0d2" stroke="#c28c48" stroke-width="2"/><path d="m75-60 22-14V-6L75 8" fill="#e1b172"/><path d="M-94-60 -70-99H62L85-60Z" fill="#f2b84b"/><path d="m-54-99-11 39h25l8-39m27 0-3 39h26l-3-39m26 0 8 39h25l-12-39" fill="#fff3d7"/><path d="M-94-60h179v13q-13 12-26 0-13 12-26 0-13 12-26 0-13 12-26 0-13 12-26 0-13 12-26 0-12 12-23 0Z" fill="#d99434"/><rect x="-67" y="-25" width="125" height="29" fill="#bc834b"/><g fill="#f2c276"><circle cx="-48" cy="-27" r="9"/><circle cx="-28" cy="-27" r="9"/><circle cx="-8" cy="-27" r="9"/></g><rect x="22" y="-36" width="25" height="16" rx="2" fill="#497d7a"/>`;
    return `${base}<path d="M-58-66H58V6H-58Z" fill="#eee8f4" stroke="#91749e" stroke-width="2"/><path d="m58-66 22-13V-7L58 6" fill="#b5a0c4"/><path d="M-68-66a68 68 0 0 1 136 0Z" fill="#af94c2" stroke="#91749e" stroke-width="2"/><path d="M-14-132Q-42-104-38-66H-18Q-22-108 6-132" fill="#d7c8e2"/><path d="m-3-112 51-39 10 13-51 39Z" fill="#3e5885"/><path d="m43-154 22 28" stroke="#203e65" stroke-width="7"/><rect x="-15" y="-34" width="30" height="40" rx="12" fill="#79638f"/>${window(-46,-45)}${window(32,-45)}`;
  }
  function landmark(id){return `<svg viewBox="-115 -180 240 220" aria-hidden="true" class="landmark-art">${building(id)}</svg>`;}
  function world(){return `<svg class="world-svg" preserveAspectRatio="none" viewBox="0 0 1200 680" fill="none" aria-hidden="true"><defs><pattern id="water-lines" width="68" height="40" patternUnits="userSpaceOnUse"><path d="M8 22h16m18-10h10" stroke="#b8d5e8" stroke-width="2" stroke-linecap="round"/></pattern><linearGradient id="sea" x2="0" y2="1"><stop stop-color="#e5f2fa"/><stop offset="1" stop-color="#c9e4f1"/></linearGradient></defs><rect width="1200" height="680" fill="url(#sea)"/><rect width="1200" height="680" fill="url(#water-lines)"/><path d="M350 150Q440 80 580 100Q700 5 820 45Q920 10 1050 50Q1180 60 1170 190Q1240 320 1150 420Q1180 560 1030 620Q900 680 780 620Q570 690 430 570Q330 500 365 390Q280 280 350 150" fill="#b8d0b9"/><path d="M350 135Q440 65 580 85Q700-10 820 30Q920-5 1050 35Q1180 45 1170 175Q1240 305 1150 405Q1180 545 1030 605Q900 665 780 605Q570 675 430 555Q330 485 365 375Q280 265 350 135" fill="#e8eddd"/><path d="M530 80Q620 200 710 230Q760 300 715 365Q660 470 805 640" stroke="#afd5e7" stroke-width="50"/><path d="M530 80Q620 200 710 230Q760 300 715 365Q660 470 805 640" stroke="#cce6ee" stroke-width="33"/><path d="M480 280 850 225 1050 180M480 280 530 510 920 485 1050 180M850 225 920 485" stroke="#d2cfbc" stroke-width="28" stroke-linejoin="round"/><path d="M480 280 850 225 1050 180M480 280 530 510 920 485 1050 180M850 225 920 485" stroke="#faf8ef" stroke-width="20" stroke-linejoin="round"/><path d="m662 251 64-10m-66 18 64-10m-25 281 63-4m-65 12 63-4" stroke="#b79e73" stroke-width="7"/>${[[410,170,1.3],[590,150,1],[640,330,1.4],[425,440,1],[630,560,1.2],[800,520,1],[1100,360,1.2],[1020,400,1],[815,120,.9],[1080,550,1.1],[940,70,.8]].map(t=>tree(...t)).join('')}<g transform="translate(495 270)">${building('investigation')}</g><g transform="translate(850 210) scale(.9)">${building('strategy')}</g><g transform="translate(525 505) scale(.88)">${building('logic')}</g><g transform="translate(925 475) scale(.9)">${building('numbers')}</g><g transform="translate(1050 140) scale(.78)">${building('decision')}</g><g transform="translate(1115 460)"><path d="m0 0 55-25 3 11L3 13Z" fill="#b99569"/><path d="m12 6 1 19m31-33 1 20" stroke="#8a755d" stroke-width="5"/></g><path d="m238 510 26 8 16-8-16 20Z" fill="#fff"/><path d="M262 485v34m0-30-15 22h15" stroke="#5c8fb0" stroke-width="2" fill="#f4bd5d"/><g fill="#fff" opacity=".75"><ellipse cx="660" cy="36" rx="58" ry="17"/><ellipse cx="697" cy="32" rx="40" ry="22"/><ellipse cx="1130" cy="610" rx="65" ry="18"/></g></svg>`;}
  function portrait(id='mira'){const colors={mira:['#b77d56','#263d61','#f2b84b'],asha:['#a16f56','#34384f','#9ec3af'],dev:['#d4a984','#4a3d44','#8ca9dc'],noor:['#b98768','#47354a','#c7a9d6']},c=colors[id]||colors.mira;return `<svg viewBox="0 0 80 80" aria-hidden="true"><circle cx="40" cy="40" r="40" fill="#e4edf7"/><path d="M8 80Q10 52 40 52T72 80" fill="${c[2]}"/><path d="M20 38Q15 6 41 8Q67 10 61 44" fill="${c[1]}"/><ellipse cx="40" cy="35" rx="18" ry="23" fill="${c[0]}"/><path d="M19 29Q22 5 44 11Q59 13 61 31Q47 27 40 19Q31 28 19 29" fill="${c[1]}"/><path d="M34 43Q40 48 46 43" stroke="#74472e" stroke-width="2" fill="none" stroke-linecap="round"/><circle cx="33" cy="34" r="1.6" fill="#253950"/><circle cx="47" cy="34" r="1.6" fill="#253950"/></svg>`;}
  function scene(id){if(id!=='attendance')return `<svg viewBox="0 0 580 290" aria-hidden="true"><rect width="580" height="290" fill="#e3edf5"/><ellipse cx="290" cy="245" rx="205" ry="30" fill="#cbded8"/>${tree(100,200,1.2)}${tree(470,190,1.5)}<g transform="translate(290 235) scale(1.25)">${building(({courtyard:'strategy',archive:'logic',market:'numbers',forecast:'decision','library-check':'investigation'})[id]||'investigation')}</g><path d="M0 260h580" stroke="#c5d4df"/><g fill="#fff"><ellipse cx="90" cy="48" rx="50" ry="12"/><ellipse cx="140" cy="40" rx="36" ry="18"/></g></svg>`;
    return `<svg viewBox="0 0 580 290" aria-hidden="true"><rect width="580" height="290" fill="#dae9f5"/><path d="M0 180Q160 130 290 160T580 150V290H0" fill="#d8e3cf"/><path d="M0 240h580v50H0" fill="#b4c4ce"/><path d="M0 268h580" stroke="#f5f7f9" stroke-width="3" stroke-dasharray="24 18"/><path d="M85 65v122m325-140v140" stroke="#71849a" stroke-width="4"/><path d="M85 65Q250 120 410 47" stroke="#4e637d" stroke-width="2" fill="none"/><g fill="#f2b84b"><path d="m99 72 18 5-13 20Z"/><path d="m146 86 19 3-11 20Z"/><path d="m197 93 18 1-8 22Z"/><path d="m247 92 18-2-5 23Z"/><path d="m297 84 18-4-3 22Z"/><path d="m349 69 17-6-1 23Z"/></g><rect x="190" y="115" width="160" height="83" rx="4" fill="#4769a5"/><path d="m182 115 88-40 88 40Z" fill="#2e4e86"/><rect x="210" y="132" width="120" height="47" rx="2" fill="#ecbd67"/><path d="M191 189h160v14H191" fill="#203e65"/><path d="M249 203h44v8h-44" fill="#71859e"/><g fill="#738eae" stroke="#4a668a" stroke-width="2">${[130,175,220,265,310,355].map((x,i)=>`<path d="M${x} 216v-18h22v18m-22-5h22m-20 0v18m18-18v18"/>`).join('')}</g><path d="M38 160h86v68H38Z" fill="#f4f6f6" stroke="#7f9ab3" stroke-width="2"/><path d="M30 159 46 135h70l16 24Z" fill="#f2b84b"/><rect x="52" y="172" width="57" height="25" fill="#9cb8cf"/><path d="M51 205h58" stroke="#567698" stroke-width="3"/><rect x="463" y="117" width="48" height="37" rx="4" fill="#fff" stroke="#557493" stroke-width="3"/><path d="M487 154v84" stroke="#557493" stroke-width="4"/><path d="M474 127h25v17h-25Z" fill="#7c9dbb"/><path d="m470 147 34-27" stroke="#b45560" stroke-width="3"/>${tree(551,204,.9)}<circle cx="520" cy="42" r="21" fill="#f5cc7a"/></svg>`;}
  function object(kind){const common='viewBox="0 0 180 110" aria-hidden="true"';if(kind==='ticket'||kind==='cost'||kind==='costs')return `<svg ${common}><path d="M20 23h140v19a12 12 0 0 0 0 24v20H20V66a12 12 0 0 0 0-24Z" fill="#f9d687" stroke="#bd914a" stroke-width="2"/><path d="M125 23v63" stroke="#bd914a" stroke-dasharray="4 4"/><path d="M40 42h59m-59 14h43m-43 14h51" stroke="#a97d3e" stroke-width="4" stroke-linecap="round"/></svg>`;
    if(kind==='travel'||kind==='counts'||kind==='probability')return `<svg ${common}><rect x="37" y="12" width="106" height="90" rx="4" fill="white" stroke="#a9bcd2" stroke-width="2"/><rect x="68" y="6" width="44" height="12" rx="3" fill="#5678a8"/><path d="M54 80V33m0 47h74" stroke="#9eb2cd" stroke-width="2"/><path d="M68 80V55m20 25V39m20 41V62" stroke="#5678a8" stroke-width="10"/><path d="M48 91h85" stroke="#c8d5e3" stroke-width="3"/></svg>`;
    if(kind==='timing'||kind==='schedule')return `<svg ${common}><rect x="39" y="11" width="102" height="73" rx="7" fill="#e2edf7" stroke="#6f8cab" stroke-width="2"/><rect x="48" y="22" width="84" height="16" fill="#234db5"/><path d="M58 51h66m-66 12h45" stroke="#86a1bd" stroke-width="4"/><path d="M90 84v23" stroke="#6f8cab" stroke-width="5"/><circle cx="121" cy="74" r="17" fill="#f6c777"/><path d="M121 64v10l7 4" stroke="#855b20" stroke-width="2" fill="none"/></svg>`;
    return `<svg ${common}><path d="M39 12h90l15 15v72H39Z" fill="#fffdf4" stroke="#c6bc9b" stroke-width="2"/><path d="M129 12v17h15" fill="#e9e0c6"/><path d="M56 37h65m-65 15h50m-50 15h65m-65 15h35" stroke="#b3ac97" stroke-width="3" stroke-linecap="round"/><path d="M104 86 151 39l7 7-47 47Z" fill="#e3ab4c"/><path d="m104 86-3 11 10-4" fill="#53647c"/></svg>`;
  }
  return {world,scene,portrait,object,landmark};
})();
